void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;
    uv.x *= iResolution.x/iResolution.y;
    uv.x -= .35;
    uv -= .5;

    vec2 still = uv;

    float anim = tan(iTime);

    uv.x *= cos(uv.y);
    uv.y *= sin(uv.x);

    uv /= tan(uv*iTime);

    float red = step(.3+anim,length(uv)/step(.1+anim,length(uv)));
    uv = still;

    uv.x *= tan(uv.y);
    uv.y *= sin(uv.x);

    uv /= cos(uv*iTime);

    float green = step(.3+anim,length(uv)/step(.1+anim,length(uv)));
    uv = still;


    uv.x *= tan(uv.y);
    uv.y *= tan(uv.x);

    uv /= sin(uv*iTime);

    float blue = step(.3+anim,length(uv)/step(.1+anim,length(uv)));

    vec3 col = vec3(red,green,blue);

    // Output to screen
    fragColor = vec4(col,1.0);
}
